// Hot batch 258: seventy-one-instruction functions no route reaches, written by hand from `tools.disasm` and verified
// by synthetic cases (float clamps, a recursive hierarchy walk, code-length runs, file reads with seeks, list relinks,
// signed and unsigned divisions by three and handle-guarded calls).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
#include "guest_call.hpp"

#include <bit>
#include <cstdint>
#include <utility>

